export function bridgeToCanonical(address){const micro=address?.micro||{},macro=address?.macro||{},e=address?.emergent||{};const planetNames=['Sun','Earth','Moon','North Node','South Node','Mercury','Venus','Mars','Jupiter','Saturn','Uranus','Neptune','Pluto'];const dims=['Movement','Evolution','Being','Design','Space'];return Object.freeze({mode:'micro',planetary:planetNames[macro.planet]||String(macro.planet??''),dimension:dims[macro.dimension]||String(macro.dimension??''),gate:(micro.gate??0)+1,line:(micro.line??0)+1,color:(micro.color??0)+1,tone:(micro.tone??0)+1,base:(micro.base??0)+1,degree:e.degree??null,minute:e.minute??null,second:e.second??null,arc:e.arcSecond??e.arc??null,zodiac:(macro.zodiac??0)+1,house:(macro.house??0)+1});}
export function canonicalKey(a){return ['planetary','dimension','gate','line','color','tone','base','degree','minute','second','arc','zodiac','house'].map(k=>`${k}=${a?.[k]??''}`).join('|');}
